using System.Security.Cryptography;
using Talewright.Core.Events;
using Talewright.Core.Identity;
using Talewright.Runtime.Saves;
using Talewright.Talemark.Compilation;
using Talewright.Talemark.Model;

namespace Talewright.Runtime.Tests;

/// <summary>
/// Saves written by the shipped engine must keep loading. These fixtures are never regenerated by tests; see
/// SaveSamples/golden/README.md before changing them.
/// </summary>
public class GoldenSaveTests
{
    private static readonly string Root = FindRoot();

    [Fact]
    public void Lost_relic_quick_save_restores_the_trigger_step()
    {
        var (save, history) = Restore("lost-relic-quick.twsave",
            "3C311827E018C96B7B19C449D25BCB8305BCF585A64939FA3C9F12EFB33025AE", LostRelic());

        Assert.Equal(11, history.Cursor);
        Assert.False(history.CanForward);
        Assert.Equal("trail.jaguar", history.Current.Scene!.Value.Value);
        AssertCampAndTrigger(history);
        Assert.Equal(2, history.State.VisitCount(new SceneId("trail.night")));
        Assert.Empty(history.Events.OfType<DiceRolled>());
        AssertSameEvidence(save, history);
    }

    [Fact]
    public void Lost_relic_named_save_restores_redo_before_the_skill_check()
    {
        var (save, history) = Restore("lost-relic-slot.twsave",
            "E51EEF0AB484A3D7FD393891AA23603B749D3A5C050FA2AA747396AF6FB9353D", LostRelic());

        Assert.Equal(13, history.Cursor);
        Assert.Equal(14, save.Choices.Count);
        Assert.True(history.CanForward);
        Assert.Equal("temple.door", history.Current.Scene!.Value.Value);
        AssertCampAndTrigger(history);
        Assert.Equal(3, history.State.VisitCount(new SceneId("trail.night")));
        Assert.Empty(history.Events.OfType<DiceRolled>());
        AssertSameEvidence(save, history);

        history.Forward();
        AssertFailedDoorCheck(history);
    }

    [Fact]
    public void Lost_relic_autosave_restores_the_failed_skill_check()
    {
        var (save, history) = Restore("lost-relic-autosave.twsave",
            "EF233D6AD3CE301EB9B6EF97861C2E318BA8C6E8212069771CE82DF3ABAD3BDC", LostRelic());

        Assert.Equal(14, history.Cursor);
        Assert.False(history.CanForward);
        AssertCampAndTrigger(history);
        AssertFailedDoorCheck(history);
        AssertSameEvidence(save, history);
    }

    [Fact]
    public void Lost_relic_trigger_checkpoint_restores_through_trigger_envelope()
    {
        var fixture = Path.Combine(Root, "engine", "tests", "Talewright.Runtime.Tests", "SaveSamples", "golden",
            "lost-relic-trigger.twtrigger");
        var bytes = File.ReadAllBytes(fixture);
        Assert.Equal("3711678F10D3B3B9A4D6C1DB1001399AB069A04E5A10960F8CA1AB9C775C6662",
            Convert.ToHexString(SHA256.HashData(bytes)));

        var (story, expected) = CreateLostRelicTriggerCheckpoint();
        Assert.Equal(bytes, TriggerSaveCodec.Encode(expected));

        var checkpoint = TriggerSaveCodec.Decode(bytes);
        Assert.Equal("courage-earned", checkpoint.TriggerId);
        var save = SaveFormat.Read(checkpoint.Data);
        var history = StoryHistory.Restore(story, checkpoint.Data);

        Assert.Equal(11, history.Cursor);
        Assert.False(history.CanForward);
        Assert.Equal("trail.jaguar", history.Current.Scene!.Value.Value);
        AssertCampAndTrigger(history);
        Assert.Equal(2, history.State.VisitCount(new SceneId("trail.night")));
        Assert.Empty(history.Events.OfType<DiceRolled>());
        AssertSameEvidence(save, history);
    }

    [Fact]
    public void Csharp_story_save_restores_through_registered_extensions()
    {
        var (save, history) = Restore("csharp-story.twsave",
            "8F877E621AB6EE86DAF18F4491478DD0374E7013452FF40A2CDA4F99F885BF95", CSharpStory());

        Assert.NotNull(save.ReplayChoiceIdentities);
        Assert.Equal(1, history.Cursor);
        Assert.Equal("ending", history.Current.Scene!.Value.Value);
        Assert.True(history.Current.IsEnded);
        Assert.Equal(1, history.State.VisitCount(new SceneId("beginning")));
        AssertSameEvidence(save, history);
    }

    private static void AssertCampAndTrigger(StoryHistory history)
    {
        Assert.Equal("explorer", history.Character?.Preset);
        Assert.Equal(2, history.State.VisitCount(new SceneId("camp.hub")));
        Assert.Equal(1, history.State.VisitCount(new SceneId("camp.supplies")));
        Assert.Equal(2, history.State.GetVariable(new VarId("supplies")));
        Assert.Equal(1, history.State.GetItemCount(EntityId.Player, new ItemId("ration")));
        Assert.Equal(10, history.State.GetStat(EntityId.Player, new StatId("courage")));
        Assert.True(history.State.HasFiredTrigger("courage-earned"));
        Assert.True(history.State.GetFlag(new FlagId("steady")));
    }

    private static void AssertFailedDoorCheck(StoryHistory history)
    {
        Assert.Equal("temple.side", history.Current.Scene!.Value.Value);
        Assert.Equal(new DiceRolled(20, 10), Assert.Single(history.Events.OfType<DiceRolled>()));
        Assert.False(history.State.GetFlag(new FlagId("door-damaged")));
    }

    private static void AssertSameEvidence(SavedGame save, StoryHistory history)
    {
        var resaved = SaveFormat.Read(history.Save(save.Summary));
        Assert.Equal(save.Choices, resaved.Choices);
        Assert.Equal(save.Cursor, resaved.Cursor);
        Assert.Equal(save.Seed, resaved.Seed);
        Assert.Equal(save.ContentFingerprint, resaved.ContentFingerprint);
        Assert.NotNull(save.ReplayEvidence);
        Assert.Equal(save.ReplayEvidence, resaved.ReplayEvidence);
        Assert.Equal(save.ReplayChoiceIdentities!.Select(Convert.ToHexString),
            resaved.ReplayChoiceIdentities!.Select(Convert.ToHexString));
    }

    private static (SavedGame Save, StoryHistory History) Restore(string file, string sha256, StoryDefinition story)
    {
        var bytes = File.ReadAllBytes(Path.Combine(Root, "engine", "tests", "Talewright.Runtime.Tests", "SaveSamples", "golden", file));
        Assert.Equal(sha256, Convert.ToHexString(SHA256.HashData(bytes)));
        return (SaveFormat.Read(bytes), StoryHistory.Restore(story, bytes));
    }

    private static StoryDefinition LostRelic() =>
        Compile(StorySource.FromDirectory(Path.Combine(Root, "samples", "LostRelic")), null);

    private static (StoryDefinition Story, TriggerSave Checkpoint) CreateLostRelicTriggerCheckpoint()
    {
        var quickSavePath = Path.Combine(Root, "engine", "tests", "Talewright.Runtime.Tests", "SaveSamples", "golden",
            "lost-relic-quick.twsave");
        var quickSave = SaveFormat.Read(File.ReadAllBytes(quickSavePath));
        var story = Compile(LostRelicWithSavingCheckpoint(), null);
        var history = new StoryHistory(story, quickSave.Seed, quickSave.Character);
        foreach (var choice in quickSave.Choices)
        {
            history.Choose(choice);
        }

        var triggerSaveId = history.TriggerSaveId;
        Assert.Equal("courage-earned", triggerSaveId);
        return (story, new TriggerSave(
            triggerSaveId ?? throw new InvalidOperationException("The trigger checkpoint did not fire."),
            history.Save(quickSave.Summary)));
    }

    private static StorySource LostRelicWithSavingCheckpoint()
    {
        var source = StorySource.FromDirectory(Path.Combine(Root, "samples", "LostRelic"));
        var files = source.Files.ToDictionary(file => file.Key, file => file.Value, StringComparer.Ordinal);
        const string trigger = "    when: player:courage >= 10\n    do: set flag:steady\n    once: true";
        var manifest = files[StorySource.ManifestFileName];
        var updatedManifest = manifest.Replace(trigger, trigger + "\n    save: true", StringComparison.Ordinal);
        Assert.NotEqual(manifest, updatedManifest);
        files[StorySource.ManifestFileName] = updatedManifest;
        return new StorySource(files, source.ImagePaths);
    }

    private static StoryDefinition CSharpStory() =>
        Compile(StorySource.FromDirectory(Path.Combine(Root, "examples", "CSharpStory", "Story", "Content")),
            global::CSharpStory.StoryExtensions.Create());

    private static StoryDefinition Compile(StorySource source, CompilerOptions? options)
    {
        var result = options is null ? StoryCompiler.Compile(source) : StoryCompiler.Compile(source, options);
        Assert.True(result.Success, string.Join("\n", result.Diagnostics));
        return result.Story!;
    }

    private static string FindRoot()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "Talewright.slnx")))
        {
            directory = directory.Parent;
        }

        Assert.NotNull(directory);
        return directory.FullName;
    }
}
